SELECT nama_departemen AS nama_departemen 
FROM analytics.attendance_department_daily GROUP BY nama_departemen ORDER BY nama_departemen ASC 
 LIMIT 1000;

SELECT DATE_TRUNC('day', tanggal) AS tanggal, 100.0 * SUM(present_days) / NULLIF(SUM(expected_days), 0) AS attendance_rate 
FROM analytics.attendance_department_daily GROUP BY DATE_TRUNC('day', tanggal) ORDER BY attendance_rate DESC 
 LIMIT 10000;
